<script setup lang="ts">definePageMeta({layout:false}); const {request}=useApi(); const email=ref(''); const sent=ref(false); async function submit(){await request('/auth/password-reset/request',{method:'POST',body:{email:email.value}});sent.value=true}</script>
<template><main class="simple-auth"><section class="card auth-box"><h1>Recuperar contraseña</h1><p>Enviaremos instrucciones si el correo pertenece a una cuenta activa.</p><form @submit.prevent="submit"><input v-model="email" class="input" type="email" required><button class="btn btn-primary">Enviar instrucciones</button></form><p v-if="sent" class="notice">Solicitud recibida. Revise su correo.</p><NuxtLink to="/admin/login">Volver al ingreso</NuxtLink></section></main></template>
